import{_ as t,o,c as d,a3 as r}from"./chunks/framework.DhF4LrUq.js";const u=JSON.parse('{"title":"Error codes","description":"The error codes users actually see - console toasts, portal messages, and CLI problems grouped by surface, what each means, and what to do about it.","frontmatter":{"description":"The error codes users actually see - console toasts, portal messages, and CLI problems grouped by surface, what each means, and what to do about it."},"headers":[],"relativePath":"reference/error-codes.md","filePath":"reference/error-codes.md"}'),a={name:"reference/error-codes.md"};function s(n,e,i,h,c,l){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="error-codes" tabindex="-1">Error codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to &quot;Error codes&quot;">​</a></h1><p>Every failure surfaces as a stable code. This page covers the codes a person actually sees — in a Console toast, a portal message, or CLI output — grouped by surface, with what it means and what to do. The complete registry, including codes only internal services and store-side connectors produce, lives in the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/error-codes.md" target="_blank" rel="noreferrer">developer registry</a>.</p><h2 id="how-errors-reach-you" tabindex="-1">How errors reach you <a class="header-anchor" href="#how-errors-reach-you" aria-label="Permalink to &quot;How errors reach you&quot;">​</a></h2><ul><li><strong>Console</strong> — a toast at the bottom of the screen: the code and the registry&#39;s one-line detail, with a <strong>trace id</strong> underneath. Quote the code and the trace id when you ask for help.</li><li><strong>Tester Portal</strong> — a toast at the bottom of the screen, the same shape as the Console&#39;s: code, one-line detail, trace id.</li><li><strong>CLI</strong> — the problem printed to your terminal plus a process <a href="/shipperdog/snapshot/how-to/automation/cli-reference#exit-codes">exit code</a> your pipeline can branch on.</li></ul><h2 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h2><p>The codes an operator meets in day-to-day administration.</p><table tabindex="0"><thead><tr><th>Code</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td><code>INVALID_REQUEST</code></td><td>A form or payload failed validation; the error names the offending field.</td><td>Fix the named field and resubmit.</td></tr><tr><td><code>UNAUTHENTICATED</code> / <code>INVALID_TOKEN</code></td><td>Your session ended or the token is invalid.</td><td>Sign in again.</td></tr><tr><td><code>FORBIDDEN</code></td><td>You hold a role, but not the one this action demands.</td><td>Check <a href="/shipperdog/snapshot/roles/">your role</a>; ask an organization admin for the authority or have the right persona act.</td></tr><tr><td><code>*_NOT_FOUND</code></td><td>The thing you addressed does not exist <strong>or</strong> you are not allowed to see it — refusals are deliberately indistinguishable (see <a href="/shipperdog/snapshot/reference/troubleshooting#a-404-for-something-you-know-exists">troubleshooting</a>).</td><td>Verify the id; if it should exist, your access is the question — ask an administrator.</td></tr><tr><td><code>RATE_LIMITED</code></td><td>Too many requests; the answer carries a <code>Retry-After</code> hint.</td><td>Wait the indicated time and retry.</td></tr><tr><td><code>MEMBER_EXISTS</code> / <code>*_TAKEN</code> / <code>*_EXISTS</code></td><td>A uniqueness rule refused the write — name, email, bundle id, build number, or a definition that already exists.</td><td>Choose a different name/value, or edit the existing entry instead of creating a twin.</td></tr><tr><td><code>LAST_ORG_ADMIN</code></td><td>The last organization administrator cannot be removed.</td><td>Grant admin to someone else first.</td></tr><tr><td><code>APPROVAL_SELF_APPROVAL</code></td><td>You created this release, so you cannot approve it — whatever roles you hold.</td><td>The named approver role decides; see <a href="/shipperdog/snapshot/how-to/console/approvals">approvals</a>.</td></tr><tr><td><code>APPROVAL_ROLE_NOT_HELD</code></td><td>The step demands a role you do not hold; the error names the required role.</td><td>Route the decision to a holder of that role.</td></tr><tr><td><code>APPROVAL_STEP_OUT_OF_ORDER</code></td><td>Sequential chains decide in order; this step is not the current one.</td><td>Decide the current step first.</td></tr><tr><td><code>GATE_OVERRIDE_INVALID</code></td><td>Only a failed or no-data gate can be overridden, exactly once.</td><td>Check the gate&#39;s state; if it passed, no override is needed.</td></tr><tr><td><code>RELEASE_TRANSITION_*</code></td><td>The lifecycle state machine refuses the crossing (illegal edge, missing reason).</td><td>The error names the current and attempted states; use the legal edge shown on the release dashboard.</td></tr><tr><td><code>RELEASE_PROMOTION_BLOCKED</code></td><td>The target ring&#39;s evaluation refused the hop; the error lists <strong>every</strong> blocker with evidence.</td><td>Fix the blockers (or <a href="/shipperdog/snapshot/how-to/console/quality-gates">override a gate</a> with a reason), then run the precheck and promote again.</td></tr><tr><td><code>RELEASE_PROMOTION_RING_SKIP</code> / <code>_RING_SPLIT</code> / <code>_RING_FINAL</code></td><td>The hop is not one legal ring step (skip, split targets, or already final).</td><td>Promote one ring at a time, per ring group; the final ring has no next hop.</td></tr><tr><td><code>ENVIRONMENT_DISABLED</code></td><td>A parked environment cannot be named by a new release.</td><td>Reactivate the environment or choose another.</td></tr><tr><td><code>INTERNAL_ERROR</code></td><td>Something unexpected failed on the platform side; no internals leak.</td><td>Retry once; if it repeats, report with the trace id.</td></tr></tbody></table><h2 id="tester-portal" tabindex="-1">Tester Portal <a class="header-anchor" href="#tester-portal" aria-label="Permalink to &quot;Tester Portal&quot;">​</a></h2><p>The codes a tester can meet — all of them are one screen away from a fix that is not yours.</p><table tabindex="0"><thead><tr><th>Code</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td><code>INVALID_INVITATION</code></td><td>The invitation link is expired, already used, or mistyped — links are single-use and live seven days.</td><td>Ask your team for a fresh invitation; see <a href="/shipperdog/snapshot/how-to/portal/accept-invite">accept an invitation</a>.</td></tr><tr><td><code>INVALID_CREDENTIALS</code></td><td>Email or password is wrong, or the account is locked or disabled.</td><td>Re-check your password; if locked, ask your team.</td></tr><tr><td><code>INVALID_TOKEN</code></td><td>Your portal session ended while you were on a page.</td><td>Sign in again — your place is kept in the app list.</td></tr><tr><td><code>DOWNLOAD_NOT_FOUND</code></td><td>The download link lapsed (links live minutes) or the build was pulled / your access changed.</td><td>Tap Download again for a fresh link; if it persists, the team pulled the build — see <a href="/shipperdog/snapshot/how-to/portal/install-android">install on Android</a>.</td></tr><tr><td><code>FEEDBACK_RELEASE_NOT_FOUND</code></td><td>The feedback could not be attached to a release you are targeted by.</td><td>Re-open the version page from your home screen and submit from there.</td></tr><tr><td><code>ATTACHMENT_REJECTED</code></td><td>An attachment broke the rules — extension (png/jpg/mp4/txt/log), size, count, or a duplicate name.</td><td>The error names the file; fix or drop it and resubmit.</td></tr></tbody></table><h2 id="cli-and-ci" tabindex="-1">CLI and CI <a class="header-anchor" href="#cli-and-ci" aria-label="Permalink to &quot;CLI and CI&quot;">​</a></h2><p>The codes the upload and release path prints (exit code 4) — the <a href="/shipperdog/snapshot/how-to/automation/cli-reference">CLI reference</a> covers the commands.</p><table tabindex="0"><thead><tr><th>Code</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td><code>ARTIFACT_FILE_TYPE_REJECTED</code></td><td>The file is not an <code>.ipa</code>/<code>.apk</code>/<code>.aab</code> matching the declared platform.</td><td>Check the extension and the <code>--platform</code> flag.</td></tr><tr><td><code>ARTIFACT_TOO_LARGE</code></td><td>The binary exceeds the upload ceiling; large files must use the resumable session path.</td><td>Let the CLI take the session path (it does automatically past the threshold).</td></tr><tr><td><code>ARTIFACT_BUILD_TAKEN</code></td><td>This version+platform already carries that build number.</td><td>Bump the build number — artifacts are immutable, never overwritten.</td></tr><tr><td><code>UPLOAD_SESSION_EXPIRED</code></td><td>The resumable session timed out before finalize.</td><td>Start a fresh upload.</td></tr><tr><td><code>ARTIFACT_NOT_VALIDATABLE</code></td><td>Revalidation applies only to a FAILED or still-VALIDATING artifact.</td><td>Check the artifact&#39;s state first (<code>artifact view</code>).</td></tr><tr><td><code>VERSION_IMMUTABLE</code></td><td>The version&#39;s artifact set is frozen (terminal state or existing distribution).</td><td>Cut a new version for new binaries.</td></tr><tr><td><code>APPLICATION_ARCHIVED</code></td><td>The application is archived; no new versions, artifacts, or releases.</td><td>An organization admin unarchives it, or you target another app.</td></tr><tr><td><code>RELEASE_ALREADY_EXISTS</code></td><td>A release already exists for this application and version.</td><td>Drive the existing one (<code>release get</code>).</td></tr><tr><td><code>RELEASE_TARGETS_INVALID</code> / <code>RELEASE_ARTIFACT_NOT_READY</code></td><td>A target tenant/group does not hold the app, or a selected artifact is not READY.</td><td>The error lists every offending entry; fix the set in one pass.</td></tr><tr><td><code>STORAGE_UNAVAILABLE</code></td><td>Object storage refused the write; a retry is safe (a fresh id, never an overwrite).</td><td>Retry the upload.</td></tr><tr><td><code>INGEST_WRITE_CONTENTION</code></td><td>The telemetry batch collided with a concurrent write.</td><td>Retry the batch — the SDK treats the <code>Retry-After</code> hint as advisory.</td></tr></tbody></table><h2 id="inbound-webhooks" tabindex="-1">Inbound webhooks <a class="header-anchor" href="#inbound-webhooks" aria-label="Permalink to &quot;Inbound webhooks&quot;">​</a></h2><p>Codes your CI system or store integration can see in receiver responses — uniform by design, so the response never hints which leg refused.</p><table tabindex="0"><thead><tr><th>Code</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td><code>WEBHOOK_SIGNATURE_REJECTED</code> (401)</td><td>A shared-secret delivery (GitHub, Jenkins, GitLab) failed authenticity — wrong secret, bad signature, stale timestamp, or no secret configured; the reason is uniform.</td><td>Re-check the configured secret on both sides and the sender&#39;s clock; see <a href="/shipperdog/snapshot/how-to/automation/webhooks">webhooks</a>.</td></tr><tr><td><code>WEBHOOK_DELIVERY_REJECTED</code> (400)</td><td>A store delivery (App Store, Google Play) failed provider verification.</td><td>Re-check the provider&#39;s signed-token configuration.</td></tr><tr><td><code>WEBHOOK_PAYLOAD_MALFORMED</code> (400)</td><td>A verified sender&#39;s body was not readable JSON.</td><td>Inspect what the provider actually posts.</td></tr><tr><td><code>WEBHOOK_PAYLOAD_TOO_LARGE</code> (413)</td><td>The delivery exceeds the payload ceiling (default 25 MB).</td><td>Send payloads within the ceiling.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The one rule underneath</p><p>A denial never confirms existence: for every resource, &quot;not found&quot; and &quot;not yours&quot; are the same bytes. When a code surprises you, check <a href="/shipperdog/snapshot/reference/troubleshooting">troubleshooting</a> before assuming a bug — and when reporting, always quote the <strong>trace id</strong>.</p></div><p><strong>Next:</strong> <a href="/shipperdog/snapshot/reference/faq">FAQ</a> — the questions people actually ask, answered from the system&#39;s real behavior.</p>',18)])])}const f=t(a,[["render",s]]);export{u as __pageData,f as default};
